function shown(kind: ExposureKind, source: string, details: Partial<Omit<ExposureSpec, 'kind' | 'source'>> = {}): ExposureSpec {
  const [label, description] = defaults[kind];
  return Object.freeze({ kind, label, description, source, ...details });
}
